/// @notice Redeeming FRESH principal in chunks pays only the floor fee: the fresh-debt exemption keeps
/// the base rate from accumulating between chunks, so the same burn that costs 2.5% in one shot costs
/// about 0.55% in forty. Aged principal, redeemed the same way, pays the escalating fee.
contract FreshChunkingTest is Test {
    address private constant OTHER = address(0x0AAA);
    address private constant CANDIDATE = address(0x0CAD);
    address private constant REDEEMER = address(0x0DEE);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    ScratchFeed private primary;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new ScratchAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        // 1 IMD = 1/2000 ETH and 1 ETH = $2000, so 1 IMD = $1.
        primary = new ScratchFeed(5e14);
        ScratchFeed health = new ScratchFeed(0.85 ether); // mat 170, gap 50, ceiling 220
        ScratchFeed spot = new ScratchFeed(5e14);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(spot)
        );
        stable = vault.stablecoin();
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(OTHER, 2_000_000 ether);
        imd.mint(CANDIDATE, 171_000 ether);
        vm.stopPrank();
        // Supply: 900k from OTHER (ratio 222, outside the band) + 100k from CANDIDATE (ratio 171).
        _open(OTHER, 2_000_000 ether, 900_000 ether);
        vm.prank(OTHER);
        stable.transfer(REDEEMER, 40_000 ether);
    }

    function _open(address who, uint256 collateral, uint256 debt) private {
        vm.startPrank(who);
        imd.approve(address(vault), collateral);
        vault.lock(collateral);
        vault.draw(debt);
        vm.stopPrank();
    }

    function _redeemInChunks(uint256 chunks, uint256 each) private returns (uint256 paid) {
        vm.startPrank(REDEEMER);
        for (uint256 i; i < chunks; ++i) {
            paid += vault.cash(each, 0, CANDIDATE);
        }
        vm.stopPrank();
    }

    function test_freshPrincipalIsNotCheaperToRedeemThanAgedPrincipal() public {
        _open(CANDIDATE, 171_000 ether, 100_000 ether);
        uint256 quoteWholeBps = vault.redemptionFeeBps(40_000 ether); // one shot: 50 + 200 = 250 bps
        assertEq(quoteWholeBps, 250, "one-shot fee for 4% of supply");

        uint256 snapshot = vm.snapshotState();

        // A: the candidate's principal is minutes old. Forty 1,000 imdUSD burns.
        uint256 paidFresh = _redeemInChunks(40, 1_000 ether);
        uint256 feeFreshBps = (40_000 ether - paidFresh) * 10_000 / 40_000 ether;
        emit log_named_uint("fee paid, fresh principal, chunked (bps)", feeFreshBps);
        emit log_named_uint("base rate left for everyone else (1e18)", vault.redemptionBaseRate());

        vm.revertToState(snapshot);

        // B: the same candidate, same chunks, after the 12-hour window has closed.
        vm.warp(block.timestamp + 13 hours);
        primary.setValue(5e14);
        uint256 paidAged = _redeemInChunks(40, 1_000 ether);
        uint256 feeAgedBps = (40_000 ether - paidAged) * 10_000 / 40_000 ether;
        emit log_named_uint("fee paid, aged principal, chunked (bps)", feeAgedBps);

        // Chunking must not let fresh principal be redeemed for less than aged principal: the fee
        // for a given size should not depend on whether the candidate borrowed this morning.
        assertLe(paidFresh, paidAged, "fresh principal was redeemed more cheaply than aged principal");
    }
}

